import java.util.*;

public class Test {
    static class State {
        long x, y;
        int v1, v2;

        State(long x, long y, int v1, int v2) {
            this.x = x;
            this.y = y;
            this.v1 = v1;
            this.v2 = v2;
        }
    }

    int r, c;
    long[][] C = new long[64][64];
    long best = Long.MAX_VALUE;
    Scanner sca = new Scanner(System.in);
    char[] cs;
    Map<Long, Long> cache = new HashMap<>();

    void buildComb() {
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    void dfs(State s) {
        long d = Math.abs(s.x - s.y);
        if (best <= 1 || d - C[s.v1][r] * C[s.v2][r] >= best) return;
        if (s.v1 == 0 && s.v2 == 0) {
            if (d < best) best = d;
            return;
        }
        if (s.v1 > 0) {
            long dy = (C[s.v1][r] - C[s.v1 - 1][r]) * C[s.v2][r];
            dfs(new State(s.x, s.y + dy, s.v1 - 1, s.v2));
        }
        if (s.v2 > 0) {
            long dx = C[s.v1][r] * (C[s.v2][r] - C[s.v2 - 1][r]);
            dfs(new State(s.x + dx, s.y, s.v1, s.v2 - 1));
        }
    }

    long solve(State s) {
        long key = (s.x * 100 + s.v1) * 100 + s.v2;
        Long cached = cache.get(key);
        if (cached != null) return cached;
        long ans = 0L;
        long d = Math.abs(s.x - s.y);
        if (d - C[s.v1][r] * C[s.v2][r] > best) {
            cache.put(key, ans);
            return ans;
        }
        if (s.v1 == 0 && s.v2 == 0) return 1L;
        char ch = cs[s.v1 + s.v2 - 1];
        if (s.v1 > 0 && ch != 'B') {
            long dy = (C[s.v1][r] - C[s.v1 - 1][r]) * C[s.v2][r];
            ans += solve(new State(s.x, s.y + dy, s.v1 - 1, s.v2));
        }
        if (s.v2 > 0 && ch != 'A') {
            long dx = C[s.v1][r] * (C[s.v2][r] - C[s.v2 - 1][r]);
            ans += solve(new State(s.x + dx, s.y, s.v1, s.v2 - 1));
        }
        cache.put(key, ans);
        return ans;
    }

    void run() {
        r = sca.nextInt();
        c = sca.nextInt();
        sca.nextLine();
        cs = sca.nextLine().toCharArray();
        buildComb();
        int n = r + c;
        int v1 = n, v2 = n;
        long x = 0, y = 0;
        while (v1 > 0 && v2 > 0) {
            if (x > y) {
                long dy = (C[v1][r] - C[v1 - 1][r]) * C[v2][r];
                y += dy;
                v1--;
            } else {
                long dx = C[v1][r] * (C[v2][r] - C[v2 - 1][r]);
                x += dx;
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfs(new State(0, 0, n, n));
        System.out.println(solve(new State(0, 0, n, n)));
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
